// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;

import "@openzeppelin/contracts/access/Ownable.sol";
import "@openzeppelin/contracts/utils/cryptography/ECDSA.sol";

/**
 * @title CloudStorageGateway
 * @notice Manages OAuth-authenticated file uploads to decentralized storage
 * @dev Integrates with off-chain OAuth provider via signed attestations
 */
contract CloudStorageGateway is Ownable {
    using ECDSA for bytes32;

    struct OAuthSession {
        address user;
        bytes32 redirectUriHash;
        uint256 expiresAt;
        bool authenticated;
        uint8 scopeLevel;
    }

    struct UploadRequest {
        bytes32 fileHash;
        uint256 size;
        address uploader;
        bytes32 sessionId;
        string contentType;
    }

    mapping(bytes32 => OAuthSession) public sessions;
    mapping(bytes32 => UploadRequest) public uploads;
    mapping(address => bool) public trustedAttestors;
    mapping(bytes32 => bool) public approvedRedirectPrefixes;

    uint256 public constant MAX_FILE_SIZE = 100 * 1024 * 1024; // 100MB
    uint256 public constant SESSION_DURATION = 3600; // 1 hour

    event SessionCreated(bytes32 indexed sessionId, address indexed user);
    event UploadAuthorized(bytes32 indexed uploadId, bytes32 indexed sessionId);
    event RedirectValidated(bytes32 indexed sessionId, bytes32 uriHash);

    constructor(address[] memory _attestors) {
        for (uint i = 0; i < _attestors.length; i++) {
            trustedAttestors[_attestors[i]] = true;
        }
    }

    function registerRedirectPrefix(bytes32 prefixHash) external onlyOwner {
        approvedRedirectPrefixes[prefixHash] = true;
    }

    /**
     * @notice Initiates OAuth session with redirect URI validation
     * @param redirectUri The callback URI for OAuth flow
     * @param nonce Client-generated nonce for replay protection
     */
    function initiateSession(
        string calldata redirectUri,
        bytes32 nonce
    ) external returns (bytes32 sessionId) {
        sessionId = keccak256(abi.encodePacked(msg.sender, nonce, block.timestamp));

        bytes32 uriHash = keccak256(abi.encodePacked(redirectUri));

        // Validate redirect URI against approved prefixes
        require(_validateRedirectUri(redirectUri), "Invalid redirect URI");

        sessions[sessionId] = OAuthSession({
            user: msg.sender,
            redirectUriHash: uriHash,
            expiresAt: block.timestamp + SESSION_DURATION,
            authenticated: false,
            scopeLevel: 0
        });

        emit SessionCreated(sessionId, msg.sender);
        emit RedirectValidated(sessionId, uriHash);
    }

    /**
     * @notice Validates redirect URI using prefix matching
     * @dev Checks that the URI starts with an approved prefix
     */
    function _validateRedirectUri(string calldata uri) internal view returns (bool) {
        bytes memory uriBytes = bytes(uri);

        // Must have minimum length for a valid URI
        if (uriBytes.length < 8) return false;

        // Extract scheme and authority (first 32 bytes or less)
        uint256 checkLen = uriBytes.length < 32 ? uriBytes.length : 32;
        bytes memory prefix = new bytes(checkLen);
        for (uint i = 0; i < checkLen; i++) {
            prefix[i] = uriBytes[i];
        }

        // Validate against registered prefixes
        bytes32 prefixHash = keccak256(prefix);

        // Also check that no path traversal or fragment injection exists
        // by ensuring the redirect doesn't contain suspicious sequences
        for (uint i = 0; i < uriBytes.length; i++) {
            if (uriBytes[i] == 0x23) return false; // '#' fragment
        }

        return approvedRedirectPrefixes[prefixHash];
    }

    /**
     * @notice Complete OAuth flow with attestor signature
     * @param sessionId The session to authenticate
     * @param callbackUri The URI that was actually called back
     * @param scopeLevel Granted permission level
     * @param attestation Signed attestation from trusted provider
     */
    function completeAuthentication(
        bytes32 sessionId,
        string calldata callbackUri,
        uint8 scopeLevel,
        bytes calldata attestation
    ) external {
        OAuthSession storage session = sessions[sessionId];
        require(session.user != address(0), "Session not found");
        require(block.timestamp < session.expiresAt, "Session expired");
        require(!session.authenticated, "Already authenticated");

        // Verify the callback URI matches the registered redirect
        bytes32 callbackHash = keccak256(abi.encodePacked(callbackUri));

        // Critical: verify callback matches original redirect registration
        // Strict equality - no normalization tolerance
        require(
            _uriMatchesSession(callbackHash, session.redirectUriHash),
            "Callback URI mismatch"
        );

        // Verify attestor signature. Bind the message to this contract instance
        // and chain id to prevent cross-contract / cross-chain signature replay.
        bytes32 message = keccak256(abi.encodePacked(
            block.chainid, address(this), sessionId, callbackUri, scopeLevel
        ));
        bytes32 ethSignedHash = message.toEthSignedMessageHash();
        address signer = ethSignedHash.recover(attestation);
        require(trustedAttestors[signer], "Untrusted attestor");

        session.authenticated = true;
        session.scopeLevel = scopeLevel;
    }

    /**
     * @notice Compares callback URI hash with session's registered redirect
     * @dev Strict equality check - no wildcards or normalization
     */
    function _uriMatchesSession(
        bytes32 callbackHash,
        bytes32 registeredHash
    ) internal pure returns (bool) {
        // Strict equality only - callback must exactly match registered redirect
        return callbackHash == registeredHash;
    }

    /**
     * @notice Authorize a file upload using authenticated session
     */
    function authorizeUpload(
        bytes32 sessionId,
        bytes32 fileHash,
        uint256 fileSize,
        string calldata contentType
    ) external returns (bytes32 uploadId) {
        OAuthSession storage session = sessions[sessionId];
        require(session.authenticated, "Not authenticated");
        require(session.user == msg.sender, "Not session owner");
        require(block.timestamp < session.expiresAt, "Session expired");
        require(fileSize <= MAX_FILE_SIZE, "File too large");
        require(session.scopeLevel >= 1, "Insufficient scope");

        uploadId = keccak256(abi.encodePacked(
            sessionId, fileHash, block.timestamp
        ));

        uploads[uploadId] = UploadRequest({
            fileHash: fileHash,
            size: fileSize,
            uploader: msg.sender,
            sessionId: sessionId,
            contentType: contentType
        });

        emit UploadAuthorized(uploadId, sessionId);
    }

    function revokeSession(bytes32 sessionId) external {
        require(sessions[sessionId].user == msg.sender || msg.sender == owner(), "Unauthorized");
        delete sessions[sessionId];
    }
}
